CREATE OR REPLACE FUNCTION public.can_manage_worker(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'superadmin') OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_user AND EXISTS(SELECT 1 FROM public.user_roles wr WHERE wr.user_id=_user AND wr.role='worker') AND public.can_manage_location(p.location_id) AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role IN ('admin','superadmin','planner'))) $$;
DO $fix$ DECLARE d text; BEGIN
SELECT pg_get_functiondef(p.oid) INTO d FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='admin_review_report';
d:=replace(d,'perform public.require_location((select location_id from public.reports where id=_report)); if _incident is not null and (select location_id from public.incidents where id=_incident) is distinct from (select location_id from public.reports where id=_report) then raise exception ''Reports can only link to incidents in the same location''; end if;','');
d:=replace(d,'if r is null then raise exception ''Report not found''; end if;','if r is null then raise exception ''Report not found''; end if; perform public.require_location(r.location_id); if _incident is not null then perform 1 from public.incidents i where i.id=_incident and i.location_id=r.location_id for update; if not found then raise exception ''Reports can only link to incidents in the same location''; end if; end if;'); EXECUTE d;
SELECT pg_get_functiondef(p.oid) INTO d FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='before_report_insert'; d:=replace(d,'where r.status not in','where r.location_id=new.location_id and r.status not in'); EXECUTE d;
END $fix$;
CREATE OR REPLACE FUNCTION public.location_nearby_reports(_lat double precision,_lng double precision,_location uuid) RETURNS TABLE(reference text, category public.waste_category,status public.report_status,created_at timestamptz,distance_m int) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT(public.has_role(auth.uid(),'resident') OR public.can_manage_location(_location)) THEN RAISE EXCEPTION 'Not authorized for this location'; END IF;
RETURN QUERY SELECT r.reference,r.category,r.status,r.created_at,(6371000*2*asin(sqrt(power(sin(radians(r.latitude-_lat)/2),2)+cos(radians(_lat))*cos(radians(r.latitude))*power(sin(radians(r.longitude-_lng)/2),2))))::int FROM public.reports r WHERE r.location_id=_location AND r.status NOT IN ('completed','rejected') AND r.created_at>now()-interval '30 days' AND abs(r.latitude-_lat)<0.003 AND abs(r.longitude-_lng)<0.003 ORDER BY 5 LIMIT 5; END $$;
REVOKE EXECUTE ON FUNCTION public.nearby_reports(double precision,double precision,public.waste_category) FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.location_nearby_reports(double precision,double precision,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.location_nearby_reports(double precision,double precision,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.superadmin_route_incident(_incident uuid,_location uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM public.require_superadmin(); PERFORM 1 FROM public.incidents WHERE id=_incident FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Incident not found'; END IF;
IF _location IS NULL OR NOT EXISTS(SELECT 1 FROM public.locations WHERE id=_location) THEN RAISE EXCEPTION 'Choose a valid location'; END IF;
IF EXISTS(SELECT 1 FROM public.assignments a JOIN public.profiles p ON p.id=a.worker_id WHERE a.incident_id=_incident AND a.status IN ('assigned','en_route','in_progress','awaiting_verification') AND p.location_id IS DISTINCT FROM _location) THEN RAISE EXCEPTION 'Assign the active worker to this location before routing the incident'; END IF;
UPDATE public.incidents SET location_id=_location,updated_at=now() WHERE id=_incident; UPDATE public.reports SET location_id=_location,updated_at=now() WHERE incident_id=_incident;
PERFORM public.audit('incident.location','incident',_incident,jsonb_build_object('location',_location)); END $$;
REVOKE EXECUTE ON FUNCTION public.superadmin_route_incident(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.superadmin_route_incident(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.superadmin_set_worker_location(_user uuid,_location uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM public.require_superadmin(); IF _location IS NULL OR NOT EXISTS(SELECT 1 FROM public.locations WHERE id=_location) THEN RAISE EXCEPTION 'Choose a valid location'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role='worker') THEN RAISE EXCEPTION 'Worker not found'; END IF;
IF EXISTS(SELECT 1 FROM public.assignments a JOIN public.incidents i ON i.id=a.incident_id WHERE a.worker_id=_user AND a.status IN ('assigned','en_route','in_progress','awaiting_verification') AND i.location_id IS NOT NULL AND i.location_id<>_location) THEN RAISE EXCEPTION 'Worker has active tasks in another location'; END IF;
PERFORM set_config('tsidat.bypass','on',true); UPDATE public.profiles SET location_id=_location,area=(SELECT name FROM public.locations WHERE id=_location) WHERE id=_user; UPDATE public.worker_applications SET service_area=(SELECT name FROM public.locations WHERE id=_location) WHERE user_id=_user; PERFORM set_config('tsidat.bypass','off',true); PERFORM public.audit('worker.location','profile',_user,jsonb_build_object('location',_location)); END $$;
REVOKE EXECUTE ON FUNCTION public.superadmin_set_worker_location(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.superadmin_set_worker_location(uuid,uuid) TO authenticated;